package buzz.walnutnest.bridge;
import android.graphics.Rect; import android.view.accessibility.AccessibilityNodeInfo; import org.json.JSONArray; import org.json.JSONObject;
final class NodeTree { private NodeTree(){} static JSONObject compact(AccessibilityNodeInfo n,int depth,int maxDepth)throws Exception{JSONObject j=new JSONObject();j.put("class",String.valueOf(n.getClassName()));j.put("text",String.valueOf(n.getText()));j.put("desc",String.valueOf(n.getContentDescription()));j.put("id",n.getViewIdResourceName());Rect r=new Rect();n.getBoundsInScreen(r);j.put("bounds",new JSONArray(new int[]{r.left,r.top,r.right,r.bottom}));j.put("clickable",n.isClickable());j.put("editable",n.isEditable());if(depth<maxDepth){JSONArray c=new JSONArray();for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null)c.put(compact(child,depth+1,maxDepth));}j.put("children",c);}return j;} }
